Clase Empleado
    Privado Definir salarioBruto Como Entero;

    Metodo Constructor(unSalario Como Entero)
        Este.salarioBruto <- unSalario;
    FinMetodo

    Publico Metodo SalarioNeto(descuento Como Entero) Como Real
        Retornar Este.salarioBruto - Este.salarioBruto * descuento / 100;
    FinMetodo
FinClase

Proceso CalcularSalario
    Definir salario Como Entero;
    Definir descuento Como Entero;
    Definir empleado Como Empleado;
    Leer salario;
    Leer descuento;
    empleado <- Nuevo Empleado(salario);
    Escribir empleado.SalarioNeto(descuento);
FinProceso
